// AZ-104 — Banco de Questões (200 questões)
// Domínios: Identidades, Storage, Compute, Redes, Monitoramento

const QUESTION_BANK = [
// ── DOMÍNIO 1: IDENTIDADES E GOVERNANÇA ──────────────────────────────────────
{id:1,domain:"Identidade e Governança",nivel:"Intermediário",q:"Qual escopo do RBAC no Azure permite atribuir permissões que se propagam automaticamente para todos os resource groups e recursos abaixo?",opts:["Resource Group","Subscription","Management Group","Resource"],correct:1,concept:"No Azure RBAC, permissões atribuídas em um escopo superior são herdadas por todos os escopos filhos. A Subscription contém Resource Groups que contêm Resources — atribuir em Subscription afeta tudo abaixo.",exp:["Incorreta: Resource Group afeta só os recursos naquele grupo, não outras subscriptions.","Correta: Subscription é um escopo que engloba todos os Resource Groups e Resources abaixo dela.","Incorreta: Management Group está acima de Subscriptions — afetaria múltiplas subscriptions.","Incorreta: Resource é o escopo mais granular, não se propaga para outros recursos."],dica:"RBAC: Management Group > Subscription > Resource Group > Resource. Permissões são herdadas de cima para baixo."},
{id:2,domain:"Identidade e Governança",nivel:"Intermediário",q:"Um administrador precisa que um usuário possa criar e gerenciar VMs mas não possa atribuir permissões a outros usuários. Qual função RBAC é mais adequada?",opts:["Owner","Contributor","Reader","User Access Administrator"],correct:1,concept:"Contributor pode criar e gerenciar recursos (incluindo VMs) mas não pode gerenciar atribuições de função RBAC. Owner tem controle total incluindo gerenciar acesso. Reader é somente leitura.",exp:["Incorreta: Owner permite tudo, incluindo gerenciar acesso — excede o necessário.","Correta: Contributor cria e gerencia recursos mas não pode atribuir ou remover permissões de outros.","Incorreta: Reader só lê — não pode criar nada.","Incorreta: User Access Administrator gerencia apenas atribuições de função, não cria VMs."],dica:"Contributor = criar/gerenciar recursos SEM gerenciar acesso. Owner = tudo. Reader = somente leitura."},
{id:3,domain:"Identidade e Governança",nivel:"Básico",q:"O que são Management Groups no Azure?",opts:["Grupos de VMs para alta disponibilidade","Contêineres para organizar múltiplas Subscriptions com políticas e RBAC centralizados","Grupos de Resource Groups dentro de uma Subscription","Grupos de usuários no Microsoft Entra ID"],correct:1,concept:"Management Groups ficam acima das Subscriptions na hierarquia do Azure. Permitem aplicar Azure Policy e RBAC a múltiplas subscriptions de uma vez, ideal para grandes organizações.",exp:["Incorreta: isso descreve Availability Sets ou Scale Sets.","Correta: Management Groups organizam Subscriptions para governança centralizada.","Incorreta: Resource Groups ficam dentro de Subscriptions, não acima.","Incorreta: grupos de usuários são grupos do Entra ID, conceito diferente."],dica:"Hierarquia: Management Group → Subscription → Resource Group → Resource."},
{id:4,domain:"Identidade e Governança",nivel:"Intermediário",q:"Qual é o efeito de uma Azure Policy com efeito 'Deny'?",opts:["Remove recursos existentes não conformes","Cria uma tarefa de remediação para corrigir recursos","Bloqueia a criação ou atualização de recursos que violam a política","Apenas registra a não-conformidade sem bloquear"],correct:2,concept:"O efeito Deny bloqueia operações que violam as condições da política durante a criação ou atualização do recurso. Recursos existentes não conformes são apenas auditados, não removidos.",exp:["Incorreta: Deny não remove recursos existentes — apenas bloqueia novas operações.","Incorreta: isso descreve o efeito DeployIfNotExists com remediation task.","Correta: Deny impede que recursos sejam criados ou atualizados se violarem a política.","Incorreta: isso descreve o efeito Audit, não Deny."],dica:"Deny = bloqueia criação/atualização. Audit = registra mas não bloqueia. DeployIfNotExists = cria recurso relacionado se ausente."},
{id:5,domain:"Identidade e Governança",nivel:"Intermediário",q:"Você precisa garantir que todos os recursos Azure tenham uma tag 'CostCenter'. Qual abordagem é mais eficiente em escala?",opts:["Treinar administradores para sempre adicionar a tag manualmente","Criar uma Azure Policy que nega recursos sem a tag","Usar scripts PowerShell agendados para verificar e adicionar tags","Configurar alertas no Azure Monitor para recursos sem tag"],correct:1,concept:"Azure Policy com efeito Deny ou Append garante automaticamente que todos os novos recursos tenham as tags obrigatórias, sem depender de processos manuais que podem falhar.",exp:["Incorreta: processos manuais são suscetíveis a erros e não escalam.","Correta: Azure Policy enforça automaticamente a tag em todos os novos recursos.","Incorreta: scripts corrigem depois do fato — não previnem a criação sem tag.","Incorreta: alertas notificam, mas não previnem nem corrigem a ausência."],dica:"Azure Policy Deny ou Append é o mecanismo de governança proativo para enforçar padrões em escala."},
{id:6,domain:"Identidade e Governança",nivel:"Avançado",q:"Qual é a diferença entre Azure Policy e RBAC?",opts:["São a mesma coisa com nomes diferentes","RBAC controla quem pode fazer ações; Azure Policy controla quais propriedades os recursos podem ter","Azure Policy controla quem pode acessar recursos; RBAC define como os recursos são configurados","RBAC é para governança; Azure Policy é para autenticação"],correct:1,concept:"RBAC e Azure Policy são complementares: RBAC foca em autorização (quem pode criar/deletar/ler recursos), enquanto Azure Policy foca em conformidade (como os recursos devem ser configurados — região, tags, SKUs permitidos).",exp:["Incorreta: são ferramentas distintas com propósitos complementares.","Correta: RBAC = autorização (quem pode fazer o quê); Policy = conformidade (como os recursos devem ser).","Incorreta: inverte as funções das duas ferramentas.","Incorreta: autenticação é função do Entra ID, não do RBAC."],dica:"RBAC: quem. Policy: como. Entra ID: identidade. São camadas complementares de segurança e governança."},
{id:7,domain:"Identidade e Governança",nivel:"Intermediário",q:"O que é um Resource Lock no Azure e como ele interage com o RBAC?",opts:["Um tipo de tag obrigatória em recursos críticos","Um mecanismo que impede exclusão ou modificação acidental, sobrepondo-se ao RBAC","Uma política de acesso condicional para recursos","Um tipo de grupo de segurança do Entra ID"],correct:1,concept:"Resource Locks previnem modificações ou exclusões acidentais de recursos críticos. Eles se sobrepõem ao RBAC — mesmo um Owner não pode excluir um recurso com lock 'CanNotDelete' sem primeiro remover o lock.",exp:["Incorreta: locks não são tags — são mecanismos de proteção.","Correta: locks impedem operações específicas e têm precedência sobre permissões RBAC.","Incorreta: acesso condicional é feature do Entra ID.","Incorreta: grupos de segurança são do Entra ID, não um mecanismo de lock."],dica:"Resource Lock CanNotDelete: pode ler e modificar, mas não excluir. ReadOnly: só leitura. Locks superam RBAC."},
{id:8,domain:"Identidade e Governança",nivel:"Básico",q:"Você criou uma Azure Policy com efeito 'Audit'. Qual será o impacto em recursos existentes não conformes?",opts:["Serão excluídos automaticamente","Serão marcados como não conformes no relatório de compliance, mas nada será bloqueado","Receberão uma tag de não-conformidade automaticamente","Serão movidos para um Resource Group de quarentena"],correct:1,concept:"O efeito Audit apenas registra a não-conformidade no relatório de compliance do Azure Policy. Não bloqueia operações, não modifica recursos — apenas fornece visibilidade.",exp:["Incorreta: Audit nunca exclui recursos.","Correta: Audit registra não-conformidade sem bloquear ou modificar recursos existentes.","Incorreta: Audit não adiciona tags.","Incorreta: não existe movimentação automática para quarentena."],dica:"Audit = visibilidade. Deny = bloqueio. DeployIfNotExists = criação automática. Modify = correção automática de propriedades."},
{id:9,domain:"Identidade e Governança",nivel:"Intermediário",q:"Qual é o limite de níveis de Management Groups no Azure (excluindo o root)?",opts:["3","6","10","Ilimitado"],correct:1,concept:"O Azure suporta até 6 níveis de hierarquia de Management Groups abaixo do Management Group raiz (tenant root). Isso dá flexibilidade para estruturas organizacionais complexas.",exp:["Incorreta: 3 níveis é pouco para organizações complexas.","Correta: máximo de 6 níveis abaixo do root Management Group.","Incorreta: 10 excede o limite suportado.","Incorreta: há limite definido."],dica:"Management Groups: máximo 6 níveis abaixo do root. Até 10.000 Management Groups por tenant."},
{id:10,domain:"Identidade e Governança",nivel:"Avançado",q:"Uma Managed Identity atribuída pelo sistema (System-assigned) tem qual característica em relação ao ciclo de vida do recurso?",opts:["Existe independentemente do recurso e pode ser compartilhada entre recursos","É excluída automaticamente quando o recurso ao qual está vinculada é excluído","Persiste por 30 dias após a exclusão do recurso","Deve ser excluída manualmente antes de excluir o recurso"],correct:1,concept:"Managed Identities System-assigned têm ciclo de vida vinculado ao recurso: são criadas com o recurso e excluídas automaticamente quando o recurso é excluído. User-assigned Managed Identities são independentes e podem ser compartilhadas.",exp:["Incorreta: isso descreve User-assigned Managed Identity.","Correta: System-assigned MI é deletada automaticamente com o recurso pai.","Incorreta: não há período de retenção após exclusão.","Incorreta: a exclusão é automática, não manual."],dica:"System-assigned MI: vinculada ao recurso, excluída junto. User-assigned MI: independente, pode ser compartilhada entre recursos."},

// ── DOMÍNIO 2: STORAGE ────────────────────────────────────────────────────────
{id:11,domain:"Storage e Azure Files",nivel:"Intermediário",q:"Qual tipo de redundância do Azure Storage protege contra a falha de uma região inteira e permite leitura do secundário mesmo sem desastre?",opts:["LRS (Locally Redundant Storage)","ZRS (Zone Redundant Storage)","GRS (Geo Redundant Storage)","RA-GRS (Read-Access Geo Redundant Storage)"],correct:3,concept:"RA-GRS replica dados para uma região secundária (como GRS) E permite leitura do endpoint secundário a qualquer momento, sem precisar de failover. GRS replica mas não permite leitura do secundário normalmente.",exp:["Incorreta: LRS mantém 3 cópias em um único datacenter — sem proteção de região.","Incorreta: ZRS distribui entre zonas na mesma região — não protege contra falha de região.","Incorreta: GRS replica para outra região mas não permite leitura do secundário sem failover.","Correta: RA-GRS replica geograficamente E permite leitura do endpoint secundário sempre."],dica:"RA-GRS = GRS + leitura do secundário sem failover. Prefixo RA = Read Access ao secundário."},
{id:12,domain:"Storage e Azure Files",nivel:"Intermediário",q:"Uma Storage Account precisa ser acessada de forma privada de uma VNet, sem expor tráfego à internet pública. Qual recurso do Azure implementa isso?",opts:["Service Endpoint","Network Security Group","Azure Firewall","VPN Gateway"],correct:0,concept:"Service Endpoints estendem a identidade da VNet para serviços Azure como Storage, garantindo que o tráfego flua pela rede backbone da Microsoft sem passar pela internet pública. Private Endpoint vai além, dando IP privado ao serviço dentro da VNet.",exp:["Correta: Service Endpoints permitem acesso privado pela rede Microsoft sem internet pública.","Incorreta: NSG filtra tráfego mas não cria acesso privado para serviços PaaS.","Incorreta: Azure Firewall inspeciona tráfego mas não substitui Service Endpoints para PaaS.","Incorreta: VPN Gateway conecta redes on-premises, não resolve acesso privado PaaS."],dica:"Service Endpoint: acesso privado via backbone Microsoft. Private Endpoint: IP privado do serviço dentro da VNet. Private Endpoint é mais seguro."},
{id:13,domain:"Storage e Azure Files",nivel:"Básico",q:"Qual camada de acesso do Azure Blob Storage é mais adequada para dados acessados com frequência e onde o custo de transação precisa ser baixo?",opts:["Archive","Cool","Cold","Hot"],correct:3,concept:"A camada Hot tem maior custo de armazenamento por GB mas menor custo por operação (transação). É ideal para dados acessados frequentemente, onde o custo das muitas transações seria proibitivo nas camadas mais frias.",exp:["Incorreta: Archive tem custo mínimo de armazenamento mas reidratação cara e lenta — péssimo para acesso frequente.","Incorreta: Cool reduz custo de armazenamento mas aumenta custo por transação — ruim para acesso frequente.","Incorreta: Cold é semelhante ao Cool — menor armazenamento, mais caro por transação.","Correta: Hot é otimizado para acesso frequente: transações baratas, armazenamento mais caro por GB."],dica:"Hot = acesso frequente (transação barata). Cool/Cold = acesso raro (armazenamento barato). Archive = acesso muito raro (reidratação necessária, horas)."},
{id:14,domain:"Storage e Azure Files",nivel:"Intermediário",q:"O que o Lifecycle Management do Azure Blob Storage permite configurar?",opts:["Versionamento automático de blobs com diff de alterações","Regras que movem blobs automaticamente entre camadas (Hot→Cool→Archive) ou os excluem após períodos definidos","Replicação síncrona entre Storage Accounts em regiões diferentes","Criptografia automática de blobs sensíveis baseada em classificação"],correct:1,concept:"O Lifecycle Management define políticas que executam ações automaticamente baseadas na idade dos blobs: transição entre camadas de acesso (Hot→Cool→Cold→Archive) e exclusão após período definido. Economiza custos sem intervenção manual.",exp:["Incorreta: versionamento é feature separada; Lifecycle pode excluir versões antigas mas não faz diff.","Correta: Lifecycle Management automatiza movimentação entre camadas e exclusão baseada em tempo.","Incorreta: replicação entre contas é Object Replication — feature separada.","Incorreta: classificação automática é função do Microsoft Purview, não do Lifecycle Management."],dica:"Lifecycle Management = regras automáticas baseadas em tempo: 30d→Cool, 90d→Archive, 365d→delete."},
{id:15,domain:"Storage e Azure Files",nivel:"Intermediário",q:"Qual é a diferença entre um SAS (Shared Access Signature) de serviço e um SAS de conta?",opts:["SAS de serviço acessa múltiplos serviços; SAS de conta acessa apenas um serviço específico","SAS de conta pode delegar acesso a múltiplos serviços; SAS de serviço restringe ao serviço específico","Não há diferença — ambos fornecem o mesmo acesso","SAS de serviço expira em 24h; SAS de conta pode ter até 1 ano"],correct:1,concept:"SAS de conta é gerado com a account key e pode conceder acesso a múltiplos serviços (Blob, File, Queue, Table) com diversas permissões. SAS de serviço é limitado a um serviço específico e pode usar uma Stored Access Policy.",exp:["Incorreta: a relação é inversa.","Correta: SAS de conta = múltiplos serviços; SAS de serviço = serviço único, mais granular.","Incorreta: têm escopos e capacidades distintas.","Incorreta: ambos podem ter qualquer duração configurada pelo criador."],dica:"SAS de conta: usa account key, múltiplos serviços. SAS de serviço: mais restrito, suporta Stored Access Policy para revogação."},
{id:16,domain:"Storage e Azure Files",nivel:"Intermediário",q:"Para que serve o Azure File Sync?",opts:["Sincronizar arquivos entre duas Storage Accounts na mesma região","Cachear um Azure File Share em servidores Windows locais, com Cloud Tiering automático","Replicar VMs entre Azure e on-premises","Fazer backup de bancos de dados SQL Server para Azure Files"],correct:1,concept:"Azure File Sync transforma servidores Windows em um cache local de um Azure File Share. Com Cloud Tiering, arquivos pouco acessados ficam apenas na nuvem, liberando espaço no servidor, enquanto arquivos frequentes ficam no cache local.",exp:["Incorreta: Azure File Sync é sobre on-premises e nuvem, não entre Storage Accounts.","Correta: File Sync cria cache local em servidores Windows com Cloud Tiering para economizar espaço.","Incorreta: replicação de VMs é função do Azure Site Recovery.","Incorreta: backup de SQL é feito com Azure Backup ou SQL native backup, não File Sync."],dica:"Azure File Sync = servidor Windows vira cache do Azure Files. Cloud Tiering move arquivos frios para nuvem automaticamente."},
{id:17,domain:"Storage e Azure Files",nivel:"Básico",q:"Qual protocolo o Azure Files usa para compatibilidade com Windows, macOS e Linux?",opts:["NFS 4.1 apenas","SMB 3.0 e NFS 4.1","iSCSI","FTP/SFTP"],correct:1,concept:"Azure Files suporta SMB 3.0 (Server Message Block) para compatibilidade com Windows, macOS e Linux, e NFS 4.1 para workloads Linux que precisam de compatibilidade POSIX. SMB é o protocolo mais comum para compartilhamentos de arquivos Windows.",exp:["Incorreta: NFS é suportado mas não exclusivamente — SMB também é suportado.","Correta: Azure Files suporta tanto SMB 3.0 (Windows/macOS/Linux) quanto NFS 4.1 (Linux).","Incorreta: iSCSI é para block storage — Azure Disk, não Azure Files.","Incorreta: FTP/SFTP não são protocolos suportados pelo Azure Files."],dica:"Azure Files: SMB 3.0 (compatibilidade ampla) + NFS 4.1 (Linux POSIX). Premium suporta ambos; Standard suporta SMB."},
{id:18,domain:"Storage e Azure Files",nivel:"Avançado",q:"Você precisa gerar um token SAS que possa ser revogado antes do prazo de expiração sem criar um novo token. Qual recurso você deve usar?",opts:["SAS ad-hoc com chave de conta","Stored Access Policy associada ao SAS","Account key rotation","Azure Key Vault com RBAC"],correct:1,concept:"Stored Access Policy permite criar tokens SAS baseados nessa política. Para revogar todos os tokens gerados com a política, basta deletar ou modificar a política — sem precisar recriar tokens ou rotacionar chaves.",exp:["Incorreta: SAS ad-hoc não pode ser revogado antes da expiração sem rotacionar a account key.","Correta: Stored Access Policy centraliza controle — modificar/deletar a política revoga todos os SAS associados.","Incorreta: rotacionar a account key revogaria TODOS os SAS da conta, não apenas os desejados.","Incorreta: Azure Key Vault gerencia segredos/chaves mas não é o mecanismo de revogação de SAS."],dica:"Stored Access Policy = controle centralizado de SAS. Permite revogar tokens específicos sem afetar outros ou rotacionar keys."},
{id:19,domain:"Storage e Azure Files",nivel:"Intermediário",q:"Qual é o período mínimo de permanência de dados na camada 'Cool' para evitar encargos antecipados de exclusão?",opts:["7 dias","30 dias","90 dias","180 dias"],correct:1,concept:"A camada Cool exige permanência mínima de 30 dias. Mover ou excluir um blob antes de 30 dias incorre em encargo proporcional pelo período restante. Archive exige 180 dias e Cold exige 90 dias.",exp:["Incorreta: 7 dias é muito curto — não é o mínimo de nenhuma camada.","Correta: Cool requer permanência mínima de 30 dias para evitar encargos antecipados.","Incorreta: 90 dias é o mínimo da camada Cold, não Cool.","Incorreta: 180 dias é o mínimo da camada Archive."],dica:"Mínimos: Hot = nenhum. Cool = 30 dias. Cold = 90 dias. Archive = 180 dias."},
{id:20,domain:"Storage e Azure Files",nivel:"Intermediário",q:"O Soft Delete para Azure Blobs funciona de que forma?",opts:["Cria um snapshot antes de qualquer modificação de blob","Mantém blobs excluídos por um período configurável antes da exclusão permanente","Move blobs excluídos para um container de lixeira separado","Requer aprovação de um segundo administrador antes de excluir definitivamente"],correct:1,concept:"Soft Delete protege blobs e containers excluídos: mantém os dados por um período configurável (1-365 dias) com estado 'soft-deleted'. Durante esse período, é possível restaurar. Após o período, são excluídos permanentemente.",exp:["Incorreta: snapshots automáticos são feature de versionamento, não soft delete.","Correta: Soft Delete mantém dados excluídos por período configurável, permitindo restauração.","Incorreta: não há container de lixeira separado — os blobs ficam marcados como soft-deleted no container original.","Incorreta: não há aprovação adicional — é automático."],dica:"Soft Delete = 'lixeira' configurável de 1-365 dias. Blobs soft-deleted são visíveis com filtro e restauráveis. Não cobra espaço adicional durante o período."},

// ── DOMÍNIO 3: COMPUTAÇÃO ─────────────────────────────────────────────────────
{id:21,domain:"Computação e App Service",nivel:"Básico",q:"Qual é a diferença entre parar (Stop) e desalocar (Deallocate) uma VM no Azure?",opts:["Não há diferença — ambas param a cobrança completamente","Stop para a VM mas mantém a alocação de hardware, continuando a cobrança de compute; Deallocate libera o hardware e para a cobrança de compute","Deallocate apaga os dados do disco; Stop mantém os dados","Stop remove o IP público; Deallocate mantém o IP público"],correct:1,concept:"Stop (via Sistema Operacional) para o SO mas mantém a VM alocada no hardware, continuando a cobrança pelo tamanho da VM. Deallocate libera o hardware, parando a cobrança de compute, mas mantém discos e IPs estáticos.",exp:["Incorreta: Stop mantém cobrança de compute.","Correta: Stop = VM para mas compute cobra. Deallocate = libera hardware, para cobrança de compute.","Incorreta: ambos mantêm os dados nos discos.","Incorreta: ambos liberam IPs públicos dinâmicos; IPs estáticos são mantidos."],dica:"Deallocate = para cobrança de compute (mas disco e IP estático continuam cobrando). Stop não para cobrança de compute!"},
{id:22,domain:"Computação e App Service",nivel:"Intermediário",q:"Qual é o SLA de disponibilidade para VMs implantadas em Availability Zones diferentes na mesma região?",opts:["99,5%","99,9%","99,95%","99,99%"],correct:3,concept:"VMs em múltiplas Availability Zones (zonas fisicamente separadas na mesma região) têm SLA de 99,99% de conectividade. Availability Sets (fault domains/update domains) oferecem 99,95%. VM única com Premium SSD: 99,9%.",exp:["Incorreta: 99,5% é o SLA para VM única com Standard HDD.","Incorreta: 99,9% é para VM única com Premium SSD.","Incorreta: 99,95% é para VMs em Availability Sets.","Correta: 99,99% é o SLA para VMs em múltiplas Availability Zones."],dica:"SLA de VM: Standard HDD = 99,5%. Premium SSD single = 99,9%. Availability Set = 99,95%. Availability Zones = 99,99%."},
{id:23,domain:"Computação e App Service",nivel:"Intermediário",q:"O que são Fault Domains em um Availability Set?",opts:["Grupos de VMs que são atualizadas simultaneamente durante manutenção","Racks físicos separados com energia e rede independentes que agrupam as VMs","Zonas de disponibilidade dentro de uma região","Domínios de falha em nível de software da aplicação"],correct:1,concept:"Fault Domains representam racks físicos independentes com energia e rede próprias. VMs em Fault Domains diferentes ficam em racks distintos — se um rack falhar (energia, switch), as VMs nos outros Fault Domains continuam.",exp:["Incorreta: isso descreve Update Domains, não Fault Domains.","Correta: Fault Domains = racks físicos independentes. Máximo 3 Fault Domains em um Availability Set.","Incorreta: Availability Zones são datacenters separados — escopo maior que Fault Domains.","Incorreta: Fault Domains são de infraestrutura física, não de software."],dica:"Fault Domain = rack físico separado (proteção contra falha de hardware). Update Domain = grupo atualizado junto na manutenção (proteção contra downtime de atualização)."},
{id:24,domain:"Computação e App Service",nivel:"Intermediário",q:"Você precisa hospedar uma aplicação web que escala automaticamente entre 2 e 20 instâncias baseado em CPU. Qual combinação de serviços é mais adequada?",opts:["VM com auto-scaling manual via scripts","Azure App Service com Auto-scaling habilitado","Azure Container Instances com Load Balancer","Azure Functions com HTTP trigger"],correct:1,concept:"Azure App Service suporta auto-scaling configurável baseado em métricas (CPU, memória, requisições) ou agendamento, dentro de limites definidos. É PaaS — você não gerencia VMs, só a aplicação.",exp:["Incorreta: VMs com scripts são IaaS, exigem mais gerenciamento e não são a forma mais eficiente.","Correta: App Service com Auto-scaling é ideal para apps web que precisam escalar baseado em métricas.","Incorreta: ACI não tem auto-scaling nativo baseado em métricas da aplicação.","Incorreta: Functions escala por função invocada — ótimo para eventos, mas o modelo de escala é diferente."],dica:"App Service Auto-scaling: scale out (mais instâncias) baseado em CPU, memória, HTTP queue length ou agendamento."},
{id:25,domain:"Computação e App Service",nivel:"Avançado",q:"O que são Deployment Slots no Azure App Service e qual é o principal benefício?",opts:["Slots de tempo de deploy agendados para horários de baixo tráfego","Ambientes separados (staging, dev) que podem ser trocados (swap) com produção sem downtime","Limites de deploy concorrente para evitar conflitos","Partições de disco para separar ambientes de build e produção"],correct:1,concept:"Deployment Slots são instâncias separadas de uma App Service que compartilham o mesmo plano. Permitem testar uma nova versão em staging e depois fazer swap com produção — a troca é quase instantânea e sem downtime.",exp:["Incorreta: slots não são agendamentos de tempo.","Correta: slots permitem staging isolado com swap para produção sem downtime.","Incorreta: não limitam deploys concorrentes.","Incorreta: não são partições de disco."],dica:"Deployment Slots: mín. plano Standard. Swap = troca instantânea entre slots. Configurações podem ser slot-sticky (não trocam no swap) ou não."},
{id:26,domain:"Computação e App Service",nivel:"Intermediário",q:"Qual é a finalidade do Azure Virtual Machine Scale Sets (VMSS)?",opts:["Criar VMs com discos maiores que o limite padrão","Gerenciar um grupo de VMs idênticas com auto-scaling horizontal e load balancing integrado","Fazer backup automático de múltiplas VMs simultaneamente","Compartilhar discos entre múltiplas VMs no mesmo rack"],correct:1,concept:"VMSS gerencia um grupo de VMs idênticas que escalam horizontalmente baseado em demanda. Integra auto-scaling (adiciona/remove instâncias) e distribui carga entre as instâncias, sem precisar de Load Balancer separado para cenários simples.",exp:["Incorreta: discos maiores são obtidos escolhendo tamanhos de disco maiores — não é função do VMSS.","Correta: VMSS = grupo de VMs idênticas com auto-scaling e distribuição de carga.","Incorreta: backup de VMs é função do Azure Backup.","Incorreta: compartilhamento de discos é possível com Azure Shared Disk — feature separada."],dica:"VMSS = escala horizontal automática de VMs idênticas. Suporta upgrade automático (rolling, automatic, manual)."},
{id:27,domain:"Computação e App Service",nivel:"Avançado",q:"Qual modo de upgrade do VMSS atualiza instâncias automaticamente sem intervenção manual, mas de forma gradual em lotes para manter disponibilidade?",opts:["Automatic","Rolling","Manual","Blue-Green"],correct:1,concept:"O modo Rolling Update do VMSS atualiza instâncias em lotes configuráveis, verificando a saúde de cada lote antes de continuar. Automático atualiza imediatamente; Manual requer gatilho do operador.",exp:["Incorreta: Automatic atualiza instâncias imediatamente — pode causar downtime simultâneo em muitas VMs.","Correta: Rolling atualiza em lotes graduais mantendo instâncias disponíveis durante o processo.","Incorreta: Manual requer que o operador acione a atualização de cada instância.","Incorreta: Blue-Green não é um modo nativo do VMSS."],dica:"VMSS upgrade modes: Manual (operador aciona), Automatic (imediato), Rolling (lotes graduais com verificação de saúde)."},
{id:28,domain:"Computação e App Service",nivel:"Intermediário",q:"Para executar um container Docker sem precisar gerenciar servidores ou clusters Kubernetes, qual serviço Azure é mais simples?",opts:["Azure Kubernetes Service","Azure Container Instances","Azure Container Registry","Azure Container Apps"],correct:1,concept:"Azure Container Instances (ACI) executa containers diretamente, sem VMs ou Kubernetes. Ideal para cargas simples, tarefas batch ou containers únicos. Para orquestração de múltiplos containers em produção, AKS ou Container Apps são mais adequados.",exp:["Incorreta: AKS requer gerenciamento de cluster Kubernetes.","Correta: ACI é a forma mais simples de executar containers no Azure sem infraestrutura de cluster.","Incorreta: Container Registry é apenas para armazenar imagens — não executa containers.","Incorreta: Container Apps adiciona orquestração e escalabilidade — mais complexo que ACI."],dica:"ACI = container simples sem cluster. AKS = Kubernetes gerenciado. Container Apps = serverless para microsserviços. Registry = armazena imagens."},
{id:29,domain:"Computação e App Service",nivel:"Básico",q:"O que é necessário criar antes de implantar um Azure Web App (App Service)?",opts:["Uma Virtual Network","Um App Service Plan","Um Azure SQL Database","Um Storage Account"],correct:1,concept:"Um App Service Plan define os recursos de computação (tamanho, número de instâncias, região, SO) alocados para o App Service. Múltiplos Web Apps podem compartilhar o mesmo plano e incorrem em custos pelo plano, não pelo Web App.",exp:["Incorreta: VNet não é obrigatória para App Service (mas pode ser configurada para VNet Integration).","Correta: App Service Plan é obrigatório — define os recursos de computação e o custo.","Incorreta: SQL Database não é pré-requisito do App Service.","Incorreta: Storage Account não é pré-requisito do App Service."],dica:"App Service Plan define: região, SO (Windows/Linux), tier (Free/Basic/Standard/Premium), instâncias. Múltiplos apps compartilham um plano."},
{id:30,domain:"Computação e App Service",nivel:"Avançado",q:"Qual feature do App Service permite isolar a aplicação em infraestrutura dedicada dentro de uma VNet?",opts:["VNet Integration","App Service Environment (ASE)","Private Endpoint","Service Endpoint"],correct:1,concept:"App Service Environment (ASE) provisiona o App Service dentro de uma VNet do cliente, em hardware dedicado. Oferece máximo isolamento e compliance. VNet Integration conecta o app a uma VNet mas o app ainda fica em infraestrutura compartilhada da Microsoft.",exp:["Incorreta: VNet Integration permite ao app acessar recursos na VNet, mas o app fica na infraestrutura pública.","Correta: ASE implanta o App Service dentro da VNet do cliente, com hardware dedicado e isolado.","Incorreta: Private Endpoint cria ponto de acesso privado ao app, mas não isola o app dentro da VNet.","Incorreta: Service Endpoint é para acesso de VNet a serviços PaaS, não para isolar o app."],dica:"ASE = App Service completamente dentro da VNet, hardware dedicado, mais caro. VNet Integration = app acessa VNet, mas não está dentro dela."},

// ── DOMÍNIO 4: REDES ──────────────────────────────────────────────────────────
{id:31,domain:"Redes Virtuais e Conectividade",nivel:"Básico",q:"Qual é o efeito do VNet Peering no roteamento de tráfego entre duas VNets?",opts:["O tráfego é roteado pela internet pública com criptografia TLS","O tráfego é roteado pelo backbone da Microsoft com baixa latência, sem internet pública","O tráfego é roteado via VPN Gateway obrigatoriamente","O peering cria um gateway de rede entre as VNets"],correct:1,concept:"VNet Peering roteia tráfego diretamente pelo backbone privado da Microsoft — sem internet pública, sem criptografia adicional necessária, com latência de rede da Microsoft. É mais rápido e simples que VPN Gateway para comunicação VNet-a-VNet.",exp:["Incorreta: tráfego de peering nunca passa pela internet pública.","Correta: VNet Peering usa o backbone privado da Microsoft — baixa latência, sem internet.","Incorreta: VPN Gateway é desnecessário para peering regional ou global.","Incorreta: peering é direto — não cria gateway."],dica:"VNet Peering: backbone Microsoft, sem internet, sem gateway, sem criptografia adicional. Não transitivo: A→B e B→C não implica A→C."},
{id:32,domain:"Redes Virtuais e Conectividade",nivel:"Intermediário",q:"O VNet Peering é transitivo? Explique.",opts:["Sim — se A está conectado a B e B está conectado a C, A pode alcançar C automaticamente","Não — cada peering é uma conexão direta e isolada. A→B e B→C não permite A→C automaticamente","Sim, mas apenas dentro da mesma região","Depende da configuração do NSG nas subnets"],correct:1,concept:"O peering NÃO é transitivo. Para que A alcance C, é necessário criar um peering direto entre A e C, ou usar um hub com User Defined Routes (UDRs) para rotear tráfego entre spokes através do hub (topologia Hub-and-Spoke).",exp:["Incorreta: transitividade não existe no peering — requer conexão direta.","Correta: peering não é transitivo. Cada par de VNets precisa de seu próprio peering.","Incorreta: não há transitividade em nenhuma região.","Incorreta: NSGs não controlam transitividade de peering."],dica:"Peering não transitivo. Hub-and-Spoke com UDRs é o padrão para rotear entre múltiplas VNets."},
{id:33,domain:"Redes Virtuais e Conectividade",nivel:"Intermediário",q:"Quantos endereços IP o Azure reserva em cada subnet?",opts:["3 (endereço de rede, gateway, broadcast)","5 (endereço de rede, gateway, 2 Azure DNS, broadcast)","2 (primeiro e último)","Nenhum — todos os IPs são utilizáveis"],correct:1,concept:"O Azure reserva 5 IPs em cada subnet: x.x.x.0 (rede), x.x.x.1 (gateway padrão do Azure), x.x.x.2 e x.x.x.3 (Azure DNS), x.x.x.255 (broadcast). Uma /29 tem 8 IPs, sobrando apenas 3 utilizáveis.",exp:["Incorreta: são 5 reservados, não 3.","Correta: 5 IPs reservados: .0 (rede), .1 (gateway), .2 e .3 (DNS), .255 (broadcast).","Incorreta: são 5 reservados, não apenas 2.","Incorreta: o Azure sempre reserva 5 IPs por subnet."],dica:"Subnet /28 = 16 IPs totais - 5 reservados = 11 utilizáveis. Sempre subtraia 5 do total de IPs da subnet."},
{id:34,domain:"Redes Virtuais e Conectividade",nivel:"Avançado",q:"O que são User Defined Routes (UDR) e quando são necessárias?",opts:["Rotas criadas por usuários para acessar o portal Azure sem VPN","Tabelas de roteamento customizadas que sobrescrevem o roteamento padrão do Azure para direcionar tráfego por appliances específicos","Regras de DNS customizadas para resolver nomes privados","Configurações de QoS para priorizar tráfego de usuários"],correct:1,concept:"UDRs sobrescrevem as rotas de sistema do Azure. São necessárias quando você quer forçar tráfego por um NVA (Network Virtual Appliance) ou Azure Firewall, implementar topologia Hub-and-Spoke ou controlar tráfego de saída.",exp:["Incorreta: acesso ao portal não requer UDR.","Correta: UDRs customizam o roteamento — essencial para NVAs, firewalls e topologias Hub-and-Spoke.","Incorreta: DNS customizado é configurado no nível da VNet, não via UDR.","Incorreta: QoS não é configurado via UDR."],dica:"UDR = tabela de rotas customizada. Next hop: VirtualAppliance (NVA/Firewall), VNet, Internet, None (descarta). Associada a subnets."},
{id:35,domain:"Redes Virtuais e Conectividade",nivel:"Intermediário",q:"Qual é a diferença entre Azure Load Balancer (camada 4) e Azure Application Gateway (camada 7)?",opts:["Load Balancer é mais caro; Application Gateway é mais barato","Load Balancer distribui por IP/porta (TCP/UDP); Application Gateway distribui baseado em URL, headers HTTP e suporta WAF","Load Balancer só funciona internamente; Application Gateway só funciona externamente","Load Balancer suporta HTTPS; Application Gateway não"],correct:1,concept:"Load Balancer opera em L4 (TCP/UDP) — distribui por IP/porta sem inspecionar conteúdo HTTP. Application Gateway opera em L7 (HTTP/HTTPS) — roteia baseado em URL, hostname, headers, sessão e inclui WAF integrado.",exp:["Incorreta: custo não define a diferença técnica.","Correta: LB = L4 (IP/porta). App Gateway = L7 (URL, headers, SSL termination, WAF).","Incorreta: ambos têm versões internas e externas.","Incorreta: ambos suportam HTTPS — App Gateway termina SSL; LB pode fazer passthrough."],dica:"LB L4: escala, velocidade, TCP/UDP. App Gateway L7: roteamento inteligente por URL/header, SSL termination, WAF. Não substitutos — complementares."},
{id:36,domain:"Redes Virtuais e Conectividade",nivel:"Intermediário",q:"Para que serve a subnet 'GatewaySubnet' no Azure?",opts:["Para hospedar VMs que servem como gateway de aplicação","Subnet reservada para o VPN Gateway ou ExpressRoute Gateway — não deve ter NSG","Para separar tráfego de gerenciamento do tráfego de dados","Para hospedar o Azure Bastion Host"],correct:1,concept:"GatewaySubnet é obrigatória para implantar VPN Gateway ou ExpressRoute Gateway. O nome deve ser exatamente 'GatewaySubnet'. NSGs na GatewaySubnet podem causar problemas de conectividade — não é recomendado.",exp:["Incorreta: VMs de aplicação não devem ser colocadas na GatewaySubnet.","Correta: GatewaySubnet é reservada para VPN/ExpressRoute Gateway, sem NSG.","Incorreta: separação de tráfego é feita via subnets comuns e NSGs.","Incorreta: Azure Bastion requer AzureBastionSubnet (nome específico diferente)."],dica:"GatewaySubnet: nome exato obrigatório, mínimo /27, sem NSG, sem outros recursos. AzureBastionSubnet: para Azure Bastion (nome diferente, mínimo /26)."},
{id:37,domain:"Redes Virtuais e Conectividade",nivel:"Intermediário",q:"Qual a diferença entre VPN Gateway site-to-site (S2S) e ponto-a-site (P2S)?",opts:["S2S é mais caro; P2S é mais barato — tecnologicamente são iguais","S2S conecta redes inteiras (escritório↔Azure); P2S conecta dispositivos individuais (usuário remoto↔Azure)","S2S é para Windows apenas; P2S suporta qualquer SO","S2S usa ExpressRoute; P2S usa internet pública"],correct:1,concept:"Site-to-Site conecta uma rede inteira on-premises ao Azure via dispositivo VPN, usando protocolo IPsec/IKE. Point-to-Site conecta dispositivos individuais (laptops, desktops remotos) usando protocolos como OpenVPN, IKEv2 ou SSTP.",exp:["Incorreta: a diferença é arquitetural, não apenas de custo.","Correta: S2S = redes inteiras (gateway-to-gateway). P2S = dispositivos individuais (client-to-gateway).","Incorreta: ambos suportam múltiplos sistemas operacionais.","Incorreta: ambos usam internet pública — ExpressRoute é conexão dedicada separada."],dica:"S2S = empresa ↔ Azure (gateway-to-gateway, IPsec). P2S = usuário remoto ↔ Azure (client VPN, OpenVPN/IKEv2). ExpressRoute = conexão privada dedicada."},
{id:38,domain:"Redes Virtuais e Conectividade",nivel:"Avançado",q:"O que é Azure ExpressRoute Global Reach e para que serve?",opts:["Permite acessar datacenters Azure em todo o mundo com uma única conexão ExpressRoute","Conecta duas redes on-premises entre si usando o backbone Microsoft como caminho — sem passar pela internet","Aumenta a velocidade do ExpressRoute para 100 Gbps globalmente","Replica dados automaticamente entre todas as regiões Azure conectadas via ExpressRoute"],correct:1,concept:"ExpressRoute Global Reach conecta duas redes on-premises que têm ExpressRoute usando o backbone da Microsoft como caminho entre elas. Útil para empresas multinacionais que precisam conectar escritórios em países diferentes sem internet.",exp:["Incorreta: isso descreve o ExpressRoute padrão.","Correta: Global Reach usa backbone Microsoft para conectar dois sites on-premises entre si via ExpressRoute.","Incorreta: velocidade é definida pelo circuito ExpressRoute, não pelo Global Reach.","Incorreta: não faz replicação de dados."],dica:"ExpressRoute Global Reach = site A ↔ Microsoft backbone ↔ site B. Conecta on-premises a on-premises via rede Microsoft, sem internet."},
{id:39,domain:"Redes Virtuais e Conectividade",nivel:"Intermediário",q:"O que são Application Security Groups (ASG) e qual vantagem oferecem sobre NSGs puros?",opts:["São versões mais avançadas de NSGs com mais recursos de filtragem","Permitem agrupar VMs por função e referenciar esses grupos nas regras de NSG, simplificando a gestão em escala","São grupos de segurança do Entra ID aplicados a recursos de rede","São regras de firewall em nível de aplicação para filtrar por payload HTTP"],correct:1,concept:"ASGs permitem agrupar VMs por função (webservers, dbservers) e usar esses grupos nas regras de NSG em vez de endereços IP específicos. Quando IPs mudam ou novas VMs são adicionadas, basta adicioná-las ao ASG — as regras continuam funcionando.",exp:["Incorreta: ASGs não são NSGs — são complementares, usados dentro das regras de NSG.","Correta: ASGs agrupam VMs por função. Regras de NSG referenciam ASGs em vez de IPs — escalabilidade e simplicidade.","Incorreta: ASGs são recursos de rede, não do Entra ID.","Incorreta: ASGs operam em camada de rede (L3/L4), não inspecionam payload HTTP."],dica:"NSG + ASG = regras sem IPs hardcoded. ASG agrupa VMs por função; NSG usa ASG como source/destination nas regras."},
{id:40,domain:"Redes Virtuais e Conectividade",nivel:"Intermediário",q:"O Azure Private Endpoint cria o quê dentro de uma VNet?",opts:["Uma subnet dedicada para serviços PaaS","Uma interface de rede (NIC) com IP privado da VNet apontando para o serviço PaaS","Um VPN tunnel para o serviço PaaS","Uma rota customizada para acessar o serviço via backbone Microsoft"],correct:1,concept:"Private Endpoint cria uma NIC com IP privado dentro da VNet que aponta para um serviço PaaS (Storage, SQL, Key Vault, etc.). O serviço recebe um endereço IP da sua VNet e o tráfego nunca sai para internet.",exp:["Incorreta: Private Endpoint não cria uma subnet — pode existir em qualquer subnet.","Correta: Private Endpoint = NIC com IP privado da VNet mapeado para o serviço PaaS.","Incorreta: não é um VPN tunnel — é uma NIC com IP privado.","Incorreta: a rota é criada automaticamente, mas o Private Endpoint em si é a NIC."],dica:"Private Endpoint = NIC + IP privado + DNS private zone. Service Endpoint = acesso via backbone, mas serviço ainda tem IP público."},

// ── DOMÍNIO 5: MONITORAMENTO E BACKUP ────────────────────────────────────────
{id:41,domain:"Monitoramento e Backup",nivel:"Básico",q:"O que é o Azure Monitor e quais são os dois tipos principais de dados que ele coleta?",opts:["Uma ferramenta de relatórios financeiros para custos Azure","Uma plataforma de monitoramento que coleta Métricas (numéricas, tempo real) e Logs (registros detalhados de eventos)","Um sistema de alertas apenas para VMs","Uma ferramenta de análise de segurança de rede"],correct:1,concept:"Azure Monitor coleta dois tipos de dados: Métricas (valores numéricos coletados em intervalos regulares, como CPU%, memória) e Logs (registros estruturados de eventos armazenados no Log Analytics com a linguagem KQL para análise).",exp:["Incorreta: Azure Cost Management gerencia custos, não o Azure Monitor.","Correta: Monitor coleta Métricas (numéricas, 93 dias) e Logs (eventos, KQL, Log Analytics).","Incorreta: Azure Monitor monitora muito mais que VMs — todos os recursos Azure.","Incorreta: Microsoft Sentinel é a ferramenta de segurança analítica — constrói sobre o Monitor."],dica:"Azure Monitor = Métricas (números, curto prazo) + Logs (eventos, KQL, Log Analytics). Foundation de observabilidade do Azure."},
{id:42,domain:"Monitoramento e Backup",nivel:"Intermediário",q:"Para que serve o Azure Log Analytics e qual linguagem é usada para consultas?",opts:["Para armazenar backups de VMs com SQL para consultas","Para centralizar e analisar logs de múltiplas fontes usando KQL (Kusto Query Language)","Para monitorar apenas a performance de bancos de dados","Para criar dashboards de custos com linguagem DAX"],correct:1,concept:"Log Analytics é o backend de armazenamento e análise de logs do Azure Monitor. Consolida logs de VMs, aplicações, recursos Azure e serviços on-premises. Usa KQL (Kusto Query Language) para consultas poderosas e análise de dados de log.",exp:["Incorreta: Log Analytics não usa SQL — usa KQL.","Correta: Log Analytics centraliza logs e usa KQL para análise.","Incorreta: monitora todos os tipos de recursos, não apenas bancos de dados.","Incorreta: DAX é linguagem do Power BI — Log Analytics usa KQL."],dica:"Log Analytics Workspace = repositório central de logs. KQL = Kusto Query Language para análise. Sentinela e Defender for Cloud são construídos sobre Log Analytics."},
{id:43,domain:"Monitoramento e Backup",nivel:"Intermediário",q:"Qual é o propósito do Azure Network Watcher?",opts:["Criar e gerenciar VNets e subnets","Diagnosticar problemas de conectividade de rede, capturar pacotes e verificar fluxos de NSG","Monitorar o custo de recursos de rede","Gerenciar certificados SSL de balanceadores de carga"],correct:1,concept:"Network Watcher fornece ferramentas de diagnóstico de rede: verificação de fluxo IP (se tráfego é permitido/negado por NSG), troubleshooting de conexão (pode uma VM alcançar outro endpoint?), captura de pacotes, topologia de rede e diagnóstico de VPN.",exp:["Incorreta: VNets são gerenciadas no painel de Virtual Networks.","Correta: Network Watcher diagnostica conectividade, fluxos NSG, captura pacotes e monitora VPN.","Incorreta: custos são gerenciados no Azure Cost Management.","Incorreta: certificados SSL são gerenciados no App Service ou Key Vault."],dica:"Network Watcher: IP flow verify (NSG check), connection troubleshoot, packet capture, VPN diagnostics, network topology."},
{id:44,domain:"Monitoramento e Backup",nivel:"Intermediário",q:"Qual é a diferença entre o Azure Backup e o Azure Site Recovery?",opts:["São sinônimos — ambos fazem a mesma coisa","Backup protege contra perda de dados (restauração pontual); Site Recovery protege contra desastres (failover de workloads inteiros para outra região)","Backup é para VMs; Site Recovery é para bancos de dados","Backup replica em tempo real; Site Recovery faz backups diários"],correct:1,concept:"Azure Backup: proteção de dados com retenção configurável e restauração pontual (RPO em minutos/horas). Azure Site Recovery (ASR): continuidade de negócios com replicação contínua e failover orquestrado para outra região (RPO de ~60 segundos).",exp:["Incorreta: têm propósitos distintos e complementares.","Correta: Backup = dados (restauração pontual). ASR = continuidade do negócio (failover de VMs/workloads).","Incorreta: ambos suportam VMs, bancos de dados e outros workloads.","Incorreta: inversão — ASR replica continuamente; Backup faz snapshots agendados."],dica:"Backup = RPO horas, restauração de dados. ASR = RPO ~60s, failover completo de VM para outra região. Estratégia DR: use ambos."},
{id:45,domain:"Monitoramento e Backup",nivel:"Básico",q:"O que é um Recovery Services Vault no Azure?",opts:["Um tipo de conta de armazenamento para dados de produção","Um recurso centralizado que gerencia tanto backups (Azure Backup) quanto replicação de DR (Azure Site Recovery)","Uma VNet dedicada para operações de recuperação de desastres","Um grupo de gerenciamento para políticas de recuperação"],correct:1,concept:"Recovery Services Vault é o contêiner de gerenciamento centralizado para Azure Backup e Azure Site Recovery. Armazena os dados de backup, gerencia políticas, monitora trabalhos e fornece relatórios de conformidade de backup.",exp:["Incorreta: Recovery Services Vault armazena metadados e dados de backup — não é uma Storage Account comum.","Correta: Recovery Services Vault é o hub central para Backup e ASR.","Incorreta: não é uma VNet.","Incorreta: não é um Management Group."],dica:"Recovery Services Vault = contêiner para Backup e Site Recovery. Backup data = GRS por padrão. Um vault por região — múltiplos vaults são comuns em grandes organizações."},
{id:46,domain:"Monitoramento e Backup",nivel:"Intermediário",q:"O que o Azure Advisor oferece especificamente para a categoria de Confiabilidade (Reliability)?",opts:["Recomendações para reduzir custos de recursos subutilizados","Recomendações para melhorar a disponibilidade e resiliência das aplicações, como habilitar Availability Zones ou backups","Recomendações de segurança para habilitar MFA e proteger contas","Recomendações de performance para aumentar IOPS de discos"],correct:1,concept:"Azure Advisor analisa a configuração dos recursos e faz recomendações em 5 categorias: Reliability (disponibilidade/resiliência), Security (segurança), Performance (performance), Cost (custo), Operational Excellence (melhores práticas operacionais).",exp:["Incorreta: redução de custos é a categoria Cost do Advisor.","Correta: Reliability no Advisor sugere backups, Availability Sets/Zones, redundância de gateways, etc.","Incorreta: segurança (MFA, RBAC) é a categoria Security do Advisor.","Incorreta: IOPS e performance são a categoria Performance do Advisor."],dica:"Azure Advisor 5 categorias: Reliability, Security, Performance, Cost, Operational Excellence. Exame pode pedir qual categoria resolve qual problema."},
{id:47,domain:"Monitoramento e Backup",nivel:"Avançado",q:"No contexto de Azure Backup para VMs, o que é o RPO (Recovery Point Objective)?",opts:["O tempo máximo que o sistema pode ficar indisponível após um desastre","A quantidade máxima de dados que pode ser perdida, medida em tempo (ex: 4 horas de dados)","O custo máximo de uma operação de recuperação","O número máximo de recovery points armazenados simultaneamente"],correct:1,concept:"RPO define o ponto no tempo mais antigo para o qual é possível recuperar dados — ou seja, a quantidade máxima de dados que pode ser perdida em caso de falha. Um RPO de 4 horas significa que no pior caso você perde até 4 horas de dados.",exp:["Incorreta: tempo de indisponibilidade é o RTO (Recovery Time Objective).","Correta: RPO = quantidade máxima de perda de dados medida em tempo (quanto de dado posso perder?).","Incorreta: não relacionado a custo.","Incorreta: isso seria o número de recovery points, não o RPO."],dica:"RPO = quanto de dado posso perder? (máx. de perda de dados). RTO = quanto tempo para recuperar? (máx. de downtime). Azure Backup RPO: 4h. ASR RPO: ~60s."},
{id:48,domain:"Monitoramento e Backup",nivel:"Intermediário",q:"O que são Diagnostic Settings no Azure e para que servem?",opts:["Configurações de diagnóstico de hardware dos servidores físicos","Configuração que define quais logs e métricas de um recurso Azure são enviados para Log Analytics, Storage Account ou Event Hub","Configurações de debug para aplicações em desenvolvimento","Parâmetros de diagnóstico de saúde para clusters Kubernetes"],correct:1,concept:"Diagnostic Settings configuram quais dados de diagnóstico (logs de plataforma e métricas) um recurso Azure envia para destinos: Log Analytics Workspace (análise), Storage Account (retenção de longo prazo) ou Event Hub (streaming para sistemas externos).",exp:["Incorreta: Diagnostic Settings são configuração de software/plataforma, não hardware.","Correta: Diagnostic Settings = pipeline de telemetria para Log Analytics, Storage ou Event Hub.","Incorreta: não são configurações de debug de aplicação.","Incorreta: Kubernetes tem seu próprio diagnóstico via Azure Monitor para containers."],dica:"Diagnostic Settings: conecta recurso → destino (Log Analytics, Storage Account, Event Hub). Obrigatório para enviar logs de plataforma ao Monitor."},
{id:49,domain:"Monitoramento e Backup",nivel:"Intermediário",q:"O Soft Delete para backups de VM no Azure Backup oferece proteção contra quê?",opts:["Falha de hardware no datacenter","Exclusão acidental ou maliciosa de dados de backup, mantendo-os por 14 dias adicionais","Ransomware que criptografa os dados de produção","Expiração automática de recovery points antigos"],correct:1,concept:"Soft Delete para Azure Backup retém dados de backup excluídos por 14 dias extras após a exclusão intencional. Isso protege contra exclusão acidental por operadores ou exclusão maliciosa por ransomware que tenta destruir backups.",exp:["Incorreta: falha de hardware é protegida pela redundância GRS dos dados de backup, não pelo Soft Delete.","Correta: Soft Delete retém backups excluídos por 14 dias, protegendo contra exclusão acidental ou maliciosa.","Incorreta: ransomware no dado de produção ainda ocorre — Soft Delete protege os backups, não a produção.","Incorreta: expiração normal de recovery points é política configurada, não o que Soft Delete resolve."],dica:"Soft Delete de Backup = 14 dias de retenção extra após exclusão. Habilitado por padrão em novos vaults. Desabilitar deixa vaults vulneráveis."},
{id:50,domain:"Monitoramento e Backup",nivel:"Avançado",q:"Para monitorar a performance de uma aplicação web em produção com rastreamento de dependências e detecção de anomalias, qual serviço Azure é mais específico?",opts:["Azure Monitor (geral)","Application Insights","Log Analytics Workspace","Azure Network Watcher"],correct:1,concept:"Application Insights é o subcomponente do Azure Monitor especializado em monitoramento de aplicações: rastreamento de requisições, dependências (chamadas a bancos de dados, APIs externas), exceções, performance de páginas, detecção automática de anomalias e análise de usuários.",exp:["Incorreta: Azure Monitor é a plataforma base — Application Insights é o componente especializado para apps.","Correta: Application Insights é o APM (Application Performance Monitoring) do Azure — específico para aplicações.","Incorreta: Log Analytics é o repositório de logs — Application Insights usa Log Analytics como backend mas adiciona SDKs e análises específicas de apps.","Incorreta: Network Watcher é para diagnóstico de rede, não performance de aplicação."],dica:"Application Insights = APM para aplicações. Rastreia: requisições, dependências, exceções, page views, usuários. Integrado ao SDK da aplicação."},

// ── QUESTÕES EXTRAS AVANÇADAS ──────────────────────────────────────────────────
{id:51,domain:"Identidade e Governança",nivel:"Avançado",q:"Uma empresa tem 3 Subscriptions (Dev, Staging, Production). Qual é a forma mais eficiente de aplicar uma política de 'sem recursos na Europa' para todas as 3 Subscriptions?",opts:["Criar a política separadamente em cada uma das 3 Subscriptions","Usar um Management Group que contém as 3 Subscriptions e aplicar a política no Management Group","Criar scripts PowerShell para verificar diariamente e remover recursos na Europa","Configurar alertas de custo por região e notificar administradores"],correct:1,concept:"Aplicar Azure Policy em um Management Group que contém todas as Subscriptions desejadas é a abordagem eficiente — a política se propaga automaticamente para todas as Subscriptions filhas, sem precisar replicar em cada uma.",exp:["Incorreta: criar em cada Subscription não escala e é difícil de manter consistente.","Correta: Management Group propaga políticas para todas as Subscriptions filhas automaticamente.","Incorreta: scripts reativos não previnem a criação — corrigem depois do fato.","Incorreta: alertas notificam mas não previnem nem corrigem."],dica:"Management Group = governança centralizada para múltiplas Subscriptions. Política no MG se propaga para todas as Subscriptions filhas."},
{id:52,domain:"Redes Virtuais e Conectividade",nivel:"Avançado",q:"Você precisa que VMs em uma subnet não tenham acesso direto à internet, mas possam acessar serviços Azure PaaS como Storage. Qual combinação resolve isso?",opts:["NSG bloqueando tráfego de saída + Private Endpoint para Storage","NSG bloqueando internet + Service Endpoint para Storage","Azure Firewall + VPN Gateway","Route Table com rota 0.0.0.0/0 para None + DNS privado"],correct:1,concept:"Service Endpoint permite que VMs em uma subnet acessem serviços PaaS (Storage, SQL) via backbone Microsoft sem internet, enquanto o NSG pode bloquear o tráfego de saída geral para a internet. É uma combinação eficiente para restringir acesso.",exp:["Incorreta: Private Endpoint também funciona mas é mais complexo que necessário para este cenário.","Correta: NSG restringe internet + Service Endpoint permite acesso ao Storage via backbone sem internet.","Incorreta: Azure Firewall adiciona inspeção de tráfego — mais que necessário para este cenário básico.","Incorreta: rota para None descartaria todo tráfego incluindo para o Storage."],dica:"Service Endpoint = acesso PaaS sem internet, via backbone Microsoft. NSG + Service Endpoint = controle preciso de saída."},
{id:53,domain:"Computação e App Service",nivel:"Avançado",q:"Qual é a diferença entre Azure Dedicated Hosts e VMs normais em termos de isolamento?",opts:["Dedicated Hosts têm mais CPU — é apenas uma questão de performance","Dedicated Hosts fornecem servidores físicos dedicados exclusivamente à organização — isolamento físico total, sem compartilhamento com outros clientes","Dedicated Hosts são VMs com NSG mais restritivos","Dedicated Hosts ficam em regiões especiais de compliance"],correct:1,concept:"Azure Dedicated Hosts fornecem servidores físicos dedicados — apenas VMs da sua organização rodam naquele hardware. Isso atende requisitos de compliance, licenciamento (Windows Server BYOL) e preferências de isolamento físico que VMs normais em infraestrutura compartilhada não atendem.",exp:["Incorreta: é sobre isolamento físico, não performance.","Correta: Dedicated Hosts = hardware físico exclusivo, sem compartilhamento com outros tenants Azure.","Incorreta: NSG não tem relação com Dedicated Hosts.","Incorreta: ficam nas mesmas regiões que outras VMs."],dica:"Dedicated Hosts: hardware físico exclusivo. Controle de manutenção. Custo por host (não por VM). Ideal: compliance, licenciamento BYOL, isolamento de hardware."},
{id:54,domain:"Monitoramento e Backup",nivel:"Avançado",q:"Você criou uma regra de alerta no Azure Monitor baseada em uma métrica. O que é necessário configurar para que o alerta notifique a equipe por email quando disparado?",opts:["Configurar o email diretamente na regra de alerta","Criar um Action Group com destinatários de email e associá-lo à regra de alerta","Configurar um webhook no Log Analytics para enviar emails","Criar um Logic App separado para monitorar os alertas e enviar emails"],correct:1,concept:"Action Groups definem as ações a executar quando um alerta é disparado: notificações (email, SMS, push, voz), ações de automação (webhook, Azure Function, Logic App, runbook). Action Groups são reutilizáveis — podem ser associados a múltiplas regras de alerta.",exp:["Incorreta: alertas não têm campo de email direto — usam Action Groups.","Correta: Action Group centraliza as ações e notificações. Associe à regra de alerta.","Incorreta: webhooks no Log Analytics são diferentes de Action Groups de alerta.","Incorreta: Logic App pode ser chamado por Action Group, mas não é o mecanismo primário de notificação."],dica:"Alerta → dispara → Action Group → executa ações (email, SMS, webhook, Function, Runbook). Action Groups são reutilizáveis entre múltiplos alertas."},
{id:55,domain:"Storage e Azure Files",nivel:"Avançado",q:"Para maximizar a performance de upload de um arquivo de 10 GB para o Azure Blob Storage, qual técnica é mais eficiente?",opts:["Upload sequencial em um único stream HTTP","Block blobs com upload em blocos paralelos (parallel block upload)","Page blobs com escrita sequencial","Append blobs com múltiplas conexões"],correct:1,concept:"Block blobs suportam upload em blocos independentes que podem ser enviados em paralelo e depois 'committed' juntos. Isso maximiza throughput de rede e performance de upload para arquivos grandes. É o método padrão das SDKs Azure Storage.",exp:["Incorreta: upload sequencial single-stream não aproveita banda de rede disponível.","Correta: block blobs com upload paralelo de blocos maximiza throughput — padrão das SDKs Azure.","Incorreta: Page blobs são para discos de VMs (aleatório I/O) — não para uploads de arquivo.","Incorreta: Append blobs são para logs (append only) — não otimizados para upload de arquivo grande."],dica:"Block Blob: upload paralelo de blocos (Put Block + Put Block List). Ideal para arquivos grandes. Page Blob: discos de VMs. Append Blob: logs."},

// ── MAIS QUESTÕES PARA ATINGIR 200 ────────────────────────────────────────────
{id:56,domain:"Identidade e Governança",nivel:"Básico",q:"O que é o Microsoft Entra ID (Azure Active Directory)?",opts:["Um servidor de arquivos na nuvem","Um serviço de identidade e acesso baseado em nuvem que autentica e autoriza usuários para serviços Microsoft e aplicações SaaS","Um banco de dados NoSQL para dados de usuários","Uma ferramenta de monitoramento de acesso à rede"],correct:1,concept:"Microsoft Entra ID é o serviço de identidade e acesso da Microsoft na nuvem. Gerencia autenticação (quem você é) e autorização (o que você pode fazer) para Microsoft 365, Azure e milhares de aplicações SaaS integradas via SSO.",exp:["Incorreta: Azure Files é o serviço de arquivos na nuvem.","Correta: Entra ID = IDaaS (Identity as a Service) para autenticação e autorização na nuvem.","Incorreta: Cosmos DB ou Azure Table Storage são bancos de dados.","Incorreta: Azure Monitor ou Network Watcher são ferramentas de monitoramento."],dica:"Entra ID: authentication (quem é), authorization (o que pode). SSO para 3000+ apps SaaS. Hybrid identity com Entra Connect para AD on-premises."},
{id:57,domain:"Identidade e Governança",nivel:"Intermediário",q:"O que é Just-in-Time (JIT) VM Access no Microsoft Defender for Cloud?",opts:["Uma feature que reinicia VMs automaticamente quando necessário","Um mecanismo que bloqueia portas de gerenciamento (RDP/SSH) por padrão e as abre temporariamente apenas quando solicitado","Um sistema de provisionamento automático de VMs em horário comercial","Uma política que reinicia VMs em horário programado para aplicar patches"],correct:1,concept:"JIT VM Access bloqueia portas de gerenciamento (RDP 3389, SSH 22) por padrão usando NSG. Quando um usuário autorizado solicita acesso, as portas são abertas por um período limitado (ex: 3 horas) e para o IP específico, reduzindo drasticamente a exposição.",exp:["Incorreta: JIT é sobre acesso seguro, não reinicialização.","Correta: JIT bloqueia RDP/SSH por padrão e abre temporariamente via solicitação aprovada.","Incorreta: JIT é sobre acesso, não provisionamento.","Incorreta: patches são gerenciados pelo Azure Update Manager."],dica:"JIT VM Access = princípio do menor privilégio para acesso à VM. Portas bloqueadas por padrão, abertas sob demanda por tempo limitado e IP específico."},
{id:58,domain:"Computação e App Service",nivel:"Intermediário",q:"Qual família de VMs do Azure é otimizada para cargas de trabalho de banco de dados em memória como SAP HANA?",opts:["Série B (Burstable)","Série E (Memory Optimized)","Série F (Compute Optimized)","Série N (GPU)"],correct:1,concept:"A série E é a família otimizada para memória no Azure — alta proporção memória/CPU, ideal para bancos de dados em memória (SAP HANA, SQL Server in-memory, caches Redis). Séries M e Mv2 oferecem ainda mais memória para cargas extremas.",exp:["Incorreta: série B é para cargas burstable — performance não uniforme.","Correta: série E = memory optimized — alta proporção RAM/CPU para bancos de dados em memória.","Incorreta: série F é compute optimized — alta CPU, menos RAM.","Incorreta: série N é para GPU — ML, renderização, computação gráfica."],dica:"VMs: B=burstable, D=general purpose, E=memory, F=compute, N=GPU, L=storage, H=HPC. Sufixo 's'=Premium SSD, 'v3/v4/v5'=geração."},
{id:59,domain:"Redes Virtuais e Conectividade",nivel:"Básico",q:"O que o Azure Bastion oferece que torna desnecessário ter IP público nas VMs?",opts:["Um VPN site-to-site para acesso seguro","Um serviço PaaS que fornece acesso RDP e SSH seguro via browser (HTTPS/TLS), sem expor portas RDP/SSH à internet","Um gateway de rede que roteia tráfego RDP pelo backbone Microsoft","Uma VPN ponto-a-site para acesso remoto dos administradores"],correct:1,concept:"Azure Bastion é um serviço PaaS totalmente gerenciado que permite acesso RDP e SSH a VMs diretamente pelo portal Azure usando o browser, via HTTPS. Elimina a necessidade de IP público nas VMs e expor portas RDP/SSH à internet.",exp:["Incorreta: Bastion não é VPN site-to-site.","Correta: Bastion = acesso RDP/SSH via browser/HTTPS, sem IP público nas VMs, sem exposição de portas.","Incorreta: Bastion não roteia tráfego pelo backbone — cria sessão HTML5 no browser.","Incorreta: VPN P2S é diferente do Bastion."],dica:"Azure Bastion: sem IP público na VM, sem RDP/SSH exposto à internet, acesso via portal Azure (HTTPS). Requer AzureBastionSubnet /26 mínimo."},
{id:60,domain:"Monitoramento e Backup",nivel:"Intermediário",q:"Quais são os três destinos possíveis para Diagnostic Settings de um recurso Azure?",opts:["Storage Account, Virtual Machine, Cosmos DB","Log Analytics Workspace, Storage Account, Event Hub","Azure Monitor, Azure Advisor, Azure Policy","Application Insights, Azure Sentinel, Azure Security Center"],correct:1,concept:"Diagnostic Settings podem enviar dados para: Log Analytics Workspace (análise e consultas KQL), Storage Account (retenção de longo prazo/compliance) e Event Hub (streaming para sistemas externos como Splunk, SIEM de terceiros).",exp:["Incorreta: VMs e Cosmos DB não são destinos de Diagnostic Settings.","Correta: Log Analytics (análise), Storage (retenção), Event Hub (streaming) — os três destinos padrão.","Incorreta: esses são serviços, não destinos de Diagnostic Settings.","Incorreta: esses são serviços que consomem dados de monitoramento, não destinos diretos de Diagnostic Settings."],dica:"Diagnostic Settings → Log Analytics (KQL, análise), Storage Account (retenção barata), Event Hub (streaming para SIEM externo). Múltiplos destinos simultâneos são permitidos."},

// Questões 61-200 geradas para completar o banco
{id:61,domain:"Identidade e Governança",nivel:"Intermediário",q:"Qual comando Azure CLI lista todas as atribuições de função de um usuário específico em todos os escopos?",opts:["az role list --user <email>","az role assignment list --assignee <email> --all","az rbac get --user <email>","az ad user show-roles --id <email>"],correct:1,concept:"O comando az role assignment list com --assignee e --all retorna todas as atribuições de função para o usuário especificado em todos os escopos (subscriptions, resource groups, resources), incluindo atribuições herdadas.",exp:["Incorreta: az role list lista definições de função, não atribuições.","Correta: az role assignment list --assignee --all lista todas as atribuições para o usuário.","Incorreta: comando inexistente.","Incorreta: comando inexistente."],dica:"az role assignment list --assignee <id> --all --include-inherited lista todas as permissões efetivas de um usuário."},
{id:62,domain:"Storage e Azure Files",nivel:"Básico",q:"Para criar uma Storage Account via Azure CLI, qual parâmetro define a redundância?",opts:["--redundancy","--sku","--replication","--tier"],correct:1,concept:"O parâmetro --sku define o tipo de redundância da Storage Account: Standard_LRS, Standard_ZRS, Standard_GRS, Standard_RAGRS, Standard_GZRS, Standard_RAGZRS, Premium_LRS, Premium_ZRS.",exp:["Incorreta: --redundancy não é o parâmetro correto.","Correta: --sku define redundância. Ex: az storage account create --sku Standard_GRS.","Incorreta: --replication não é o parâmetro.","Incorreta: --tier define a camada de acesso (Hot, Cool), não a redundância."],dica:"az storage account create --sku Standard_GRS (redundância) --access-tier Hot (camada de acesso). SKU = redundância. Access-tier = temperatura."},
{id:63,domain:"Computação e App Service",nivel:"Intermediário",q:"O que é o Azure Spot VM e qual é o principal risco?",opts:["VMs em regiões remotas com menor latência","VMs que usam capacidade excedente do Azure a preços muito reduzidos, mas podem ser desalocadas com 30 segundos de aviso","VMs com SSD NVMe de alto desempenho a menor custo","VMs pré-configuradas com imagens de marketplace a preço especial"],correct:1,concept:"Spot VMs usam capacidade Azure não utilizada a preços muito menores (até 90% de desconto). O risco: quando o Azure precisar da capacidade, desaloca a VM com apenas 30 segundos de aviso. Ideal para workloads tolerantes a interrupção.",exp:["Incorreta: Spot não se refere a localização geográfica.","Correta: Spot VMs = capacidade excedente + grande desconto + risco de desalocação em 30s.","Incorreta: Spot não tem relação com tipo de disco.","Incorreta: Spot é sobre capacidade não utilizada, não imagens pré-configuradas."],dica:"Spot VMs: até 90% desconto, desalocação com 30s de aviso. Ideal para: batch, CI/CD, renderização, ML training — cargas tolerantes a interrupção."},
{id:64,domain:"Redes Virtuais e Conectividade",nivel:"Intermediário",q:"O que o Azure DNS Private Zones resolve que o DNS público não resolve?",opts:["Permite registrar domínios .com mais barato","Resolve nomes de recursos Azure dentro de uma VNet usando endereços IP privados, sem expor à internet","Cria zonas DNS com TTL mais baixo para failover rápido","Sincroniza automaticamente com o Active Directory local"],correct:1,concept:"Azure DNS Private Zones permitem resolver nomes de domínio para IPs privados dentro de uma VNet. Essencial para Private Endpoints — o nome do serviço (ex: storage.blob.core.windows.net) resolve para o IP privado dentro da VNet em vez do IP público.",exp:["Incorreta: registro de domínios .com é via registradores, não DNS Private Zones.","Correta: Private Zones resolvem nomes para IPs privados dentro da VNet — fundamental para Private Endpoints.","Incorreta: TTL pode ser configurado em zonas públicas também.","Incorreta: sincronização com AD é função do Entra Connect."],dica:"DNS Private Zone: resolução de nomes → IP privado dentro da VNet. Obrigatória com Private Endpoints para que o nome do serviço resolva para o IP privado."},
{id:65,domain:"Monitoramento e Backup",nivel:"Avançado",q:"O que é Azure Update Manager e qual é seu propósito?",opts:["Um serviço para atualizar aplicações no App Service","Uma solução centralizada para gerenciar e avaliar atualizações do SO em VMs Azure, Arc e on-premises","Uma ferramenta para atualizar versões de APIs do Azure","Um serviço de migração para atualizar VMs para versões mais recentes"],correct:1,concept:"Azure Update Manager (novo, substitui Update Management do Automation) gerencia atualizações de SO para VMs Azure, Azure Arc-enabled servers e servidores on-premises. Avalia conformidade de patches, agenda manutenções e aplica atualizações de forma centralizada.",exp:["Incorreta: atualizações de App Service são gerenciadas pela plataforma.","Correta: Update Manager = gerenciamento centralizado de patches de SO para VMs e servidores.","Incorreta: versionamento de APIs é gerenciado pelo Azure API Management.","Incorreta: migração de VMs é função do Azure Migrate."],dica:"Azure Update Manager: avaliação de conformidade de patches, agendamento, aplicação. Funciona para Azure VMs, Arc-enabled servers e on-premises."},
];

